-- METAECM.V_ECM_ACLS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_ACLS" ("ACL_ID", "NAME", "TYPE", "OWNER_ID", "OWNER_IS_GROUP", "IS_DEFAULT") AS
SELECT A.ACL_ID, A.NAME, A.TYPE, A.OWNER_ID, A.OWNER_IS_GROUP, A.IS_DEFAULT
FROM FW_ACLS A;

COMMENT ON TABLE METAECM.V_ECM_ACLS IS '권한. 폴더와 문서의 ACL_ID가 가리키는 권한 하나당 한 행. 키는 ACL_ID';
COMMENT ON COLUMN METAECM.V_ECM_ACLS.ACL_ID IS '권한 ID(FW_ACLS.ACL_ID). 폴더와 문서의 ACL_ID가 이 값을 가리킨다';
COMMENT ON COLUMN METAECM.V_ECM_ACLS.NAME IS 'FW_ACLS.NAME: 권한명';
COMMENT ON COLUMN METAECM.V_ECM_ACLS."TYPE" IS '권한 종류(FW_ACLS.TYPE): PRIVATE 주인(사용자나 부서)의 권한, PUBLIC 공용 권한, PROJECT 참여자시트가 관리하는 프로젝트 폴더 권한';
COMMENT ON COLUMN METAECM.V_ECM_ACLS.OWNER_ID IS '주인 ID(FW_ACLS.OWNER_ID). OWNER_IS_GROUP이 1이면 부서 ID이고 0이면 사용자 ID다';
COMMENT ON COLUMN METAECM.V_ECM_ACLS.OWNER_IS_GROUP IS '1이면 주인(OWNER_ID)이 부서다(FW_ACLS.OWNER_IS_GROUP)';
COMMENT ON COLUMN METAECM.V_ECM_ACLS.IS_DEFAULT IS '1이면 부서마다 하나인 부서 기본 권한이다(FW_ACLS.IS_DEFAULT)';


-- METAECM.V_ECM_ACL_ITEMS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_ACL_ITEMS" ("ACL_ID", "ACCESSOR_ID", "ACCESSOR_IS_GROUP", "ACCESSOR_IS_ALIAS", "CAN_BROWSE", "CAN_READ", "CAN_CREATE", "CAN_UPDATE", "CAN_DELETE", "CAN_CANCEL_CHECKOUT", "CAN_CHANGE_PERMISSION") AS
SELECT I.ACL_ID, I.ACCESSOR_ID, I.ACCESSOR_IS_GROUP, I.ACCESSOR_IS_ALIAS, I.CAN_BROWSE, I.CAN_READ, I.CAN_CREATE, I.CAN_UPDATE,
       I.CAN_DELETE, I.CAN_CANCEL_CHECKOUT, I.CAN_CHANGE_PERMISSION
FROM FW_ACL_ITEMS I;

COMMENT ON TABLE METAECM.V_ECM_ACL_ITEMS IS '권한 항목. 권한마다 대상 하나당 한 행. 키는 ACL_ID와 ACCESSOR_ID';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.ACL_ID IS '권한 ID(V_ECM_ACLS.ACL_ID)';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.ACCESSOR_ID IS '대상 ID(FW_ACL_ITEMS.ACCESSOR_ID). 사용자, 부서, 프로젝트 그룹, 별칭 가운데 무엇인지는 ACCESSOR_IS_ALIAS와 ACCESSOR_IS_GROUP이 정한다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.ACCESSOR_IS_GROUP IS 'ACCESSOR_IS_ALIAS가 0일 때 1이면 대상 ID가 부서(V_ECM_GROUPS)나 프로젝트 그룹(V_ECM_PROJECT_GROUPS)이고 0이면 사용자(V_ECM_USERS)다. 별칭 줄은 비어 있을 수 있다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.ACCESSOR_IS_ALIAS IS '1이면 대상 ID가 별칭(V_ECM_ALIASES)이다. PJ_로 시작하는 별칭은 같은 ID인 프로젝트 그룹의 멤버가 대상이다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_BROWSE IS '목록 보기 권한(FW_ACL_ITEMS.CAN_BROWSE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_READ IS '읽기 권한(FW_ACL_ITEMS.CAN_READ): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_CREATE IS '만들기 권한(FW_ACL_ITEMS.CAN_CREATE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_UPDATE IS '수정 권한(FW_ACL_ITEMS.CAN_UPDATE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_DELETE IS '삭제 권한(FW_ACL_ITEMS.CAN_DELETE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_CANCEL_CHECKOUT IS '잠금 풀기 권한(FW_ACL_ITEMS.CAN_CANCEL_CHECKOUT): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ACL_ITEMS.CAN_CHANGE_PERMISSION IS '권한 변경 권한(FW_ACL_ITEMS.CAN_CHANGE_PERMISSION): 1 있음, 0 없음';


-- METAECM.V_ECM_ACL_READERS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_ACL_READERS" ("ACL_ID", "PRINCIPAL_TYPE", "PRINCIPAL_ID", "CAN_BROWSE", "CAN_READ") AS
SELECT I.ACL_ID,
       CASE WHEN I.ACCESSOR_IS_ALIAS = 1 AND I.ACCESSOR_ID = 'OWNER' THEN 'OWNER'
            WHEN I.ACCESSOR_IS_ALIAS = 1 AND I.ACCESSOR_ID = 'OGROUP' THEN 'OGROUP'
            WHEN I.ACCESSOR_IS_ALIAS = 1 AND I.ACCESSOR_ID LIKE 'PJ\_%' ESCAPE '\' THEN 'PROJECT_GROUP'
            WHEN I.ACCESSOR_IS_ALIAS = 1 THEN 'ALIAS'
            WHEN I.ACCESSOR_IS_GROUP = 1 AND NOT EXISTS (SELECT 1 FROM FW_GROUPS G WHERE G.GROUP_ID = I.ACCESSOR_ID)
                AND EXISTS (SELECT 1 FROM FW_PROJECT_GROUPS P WHERE P.GROUP_ID = I.ACCESSOR_ID) THEN 'PROJECT_GROUP'
            WHEN I.ACCESSOR_IS_GROUP = 1 THEN 'DEPT'
            ELSE 'USER' END AS PRINCIPAL_TYPE,
       I.ACCESSOR_ID AS PRINCIPAL_ID, I.CAN_BROWSE, I.CAN_READ
FROM FW_ACL_ITEMS I
WHERE EXISTS (SELECT 1 FROM FW_ACLS A WHERE A.ACL_ID = I.ACL_ID)
  AND (I.ACCESSOR_IS_ALIAS = 1 OR (I.ACCESSOR_IS_ALIAS = 0 AND I.ACCESSOR_IS_GROUP IN (0, 1)))
UNION ALL
SELECT A.ACL_ID, 'ROLE' AS PRINCIPAL_TYPE, R.ROLE_ID AS PRINCIPAL_ID,
       CASE WHEN R.ROLE_ID = 'LEADER' THEN 1
            ELSE (SELECT NVL(MAX(T.CAN_BROWSE), 0) FROM FW_ROLE_ITEMS T WHERE T.ROLE_ID = R.ROLE_ID AND T.RESOURCE_TYPE = 'DOCUMENT') END AS CAN_BROWSE,
       CASE WHEN R.ROLE_ID = 'LEADER' THEN 1
            ELSE (SELECT NVL(MAX(T.CAN_READ), 0) FROM FW_ROLE_ITEMS T WHERE T.ROLE_ID = R.ROLE_ID AND T.RESOURCE_TYPE = 'DOCUMENT') END AS CAN_READ
FROM FW_ACLS A
         CROSS JOIN FW_ROLES R
WHERE R.ROLE_ID <> 'STANDARD_ADMIN'
  AND (R.ROLE_ID = 'LEADER'
    OR EXISTS (SELECT 1 FROM FW_ROLE_ITEMS T WHERE T.ROLE_ID = R.ROLE_ID AND T.RESOURCE_TYPE = 'DOCUMENT' AND (T.CAN_BROWSE = 1 OR T.CAN_READ = 1)));

COMMENT ON TABLE METAECM.V_ECM_ACL_READERS IS 'ACL 항목과 역할의 문서 권한을 합친 대상별 목록 보기·읽기 권한 값. 키는 ACL_ID, PRINCIPAL_TYPE, PRINCIPAL_ID. 허용 여부는 CAN_BROWSE와 CAN_READ로 판단하며 공유(V_ECM_SHARES)는 별도다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_READERS.ACL_ID IS '권한 ID(V_ECM_ACLS.ACL_ID). 문서의 권한 칸(V_ECM_FILES.DOC_ACL_ID, V_ECM_PROJECT_FILES.ACL_ID)이 이 값을 가리킨다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_READERS.PRINCIPAL_TYPE IS '대상 종류: USER 사용자, DEPT 부서, PROJECT_GROUP 프로젝트 그룹(PJ_ 별칭 포함), ALIAS 별칭, ROLE 역할, OWNER 문서를 올린 사람, OGROUP 문서를 올린 사람의 부서. OWNER와 OGROUP은 문서마다 대상이 달라지는 표시다. OWNER는 문서를 올린 사람(V_ECM_FILES.DOC_CREATOR_ID, V_ECM_PROJECT_FILES.CREATOR_ID) 한 명이 대상이다. OGROUP은 올린 사람이 속한 부서(V_ECM_USER_GROUPS)를 기준으로 한다. 그 부서 가운데 하나에 속한 사용자가 대상이다. ROLE 줄은 그 역할을 가진 사용자가 권한 항목과 상관없이 모든 문서에 받는 권한이다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_READERS.PRINCIPAL_ID IS '대상 ID. USER는 사용자 ID, DEPT는 부서 ID, PROJECT_GROUP은 프로젝트 그룹 ID, ALIAS는 별칭 ID(WORLD 전체, ALIAS_EXEC 임원 그룹 등), ROLE은 역할 ID이고 OWNER와 OGROUP 표시는 OWNER, OGROUP이다. 임원 그룹(ALIAS_EXEC)과 회사실적조회 그룹(ALIAS_PERF)은 구성원을 정한 곳이 아직 없어 해당하는 사용자가 없다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_READERS.CAN_BROWSE IS '문서 목록 보기 권한: 1 있음, 0 없음. 권한 항목 줄은 항목 값(V_ECM_ACL_ITEMS.CAN_BROWSE)이고 ROLE 줄은 그 역할의 문서 권한 설정 값(V_ECM_ROLE_ITEMS의 DOCUMENT 줄)이다. 부서장/팀장(LEADER)은 늘 1이다';
COMMENT ON COLUMN METAECM.V_ECM_ACL_READERS.CAN_READ IS '문서 읽기 권한: 1 있음, 0 없음. 문서를 열어 내용과 첨부 파일을 보는 권한이고 목록 보기만 있는 줄로는 읽지 못한다. 권한 항목 줄은 항목 값(V_ECM_ACL_ITEMS.CAN_READ)이고 ROLE 줄은 그 역할의 문서 권한 설정 값(V_ECM_ROLE_ITEMS의 DOCUMENT 줄)이다. 부서장/팀장(LEADER)은 늘 1이다';


-- METAECM.V_ECM_ALIASES source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_ALIASES" ("ALIAS_ID", "NAME", "VALUE", "TYPE", "IS_SYSTEM") AS
SELECT A.ALIAS_ID, A.NAME, A.VALUE, A.TYPE, A.IS_SYSTEM
FROM FW_ALIASES A;

COMMENT ON TABLE METAECM.V_ECM_ALIASES IS '별칭. 권한 항목과 공유의 대상이 되는 별칭 하나당 한 행. 키는 ALIAS_ID';
COMMENT ON COLUMN METAECM.V_ECM_ALIASES.ALIAS_ID IS '별칭 ID(FW_ALIASES.ALIAS_ID). 시스템 별칭은 WORLD 전체, OWNER 소유자, OGROUP 소유자의 그룹, ALIAS_EXEC 임원 그룹, ALIAS_PERF 회사실적조회 그룹이고 PJ_로 시작하면 같은 ID인 프로젝트 그룹이다';
COMMENT ON COLUMN METAECM.V_ECM_ALIASES.NAME IS 'FW_ALIASES.NAME: 별칭명';
COMMENT ON COLUMN METAECM.V_ECM_ALIASES.VALUE IS '별칭 값(FW_ALIASES.VALUE). 회사 별칭은 회사 코드(V_ECM_GROUPS.CORP_CD)이고 그 밖의 별칭은 별칭 ID와 같다';
COMMENT ON COLUMN METAECM.V_ECM_ALIASES."TYPE" IS '별칭 종류(FW_ALIASES.TYPE): USER, GROUP';
COMMENT ON COLUMN METAECM.V_ECM_ALIASES.IS_SYSTEM IS '1이면 제품이 정한 시스템 별칭이다(FW_ALIASES.IS_SYSTEM). 프로젝트 별칭은 0이다';


-- METAECM.V_ECM_FILES source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_FILES" ("DOC_SERIES_ID", "FOLDER_ID", "MAP_ID", "MAP_NAME", "FOLDER_PATH", "PROJECT_ID", "DOC_ID", "DOC_NAME", "DOC_TYPE_ID", "DOC_TYPE_NAME", "DOC_FILE_COUNT", "DOC_ROOT_ID", "DOC_STEM_ID", "DOC_IS_CURRENT", "DOC_VERSION_NUMBER", "DOC_VERSION_NOTE", "DOC_DESCRIPTION", "DOC_IS_LOCKED", "DOC_LOCK_OWNER_ID", "DOC_LOCK_OWNER_NAME", "DOC_LOCKED_DATE", "DOC_RETENTION", "DOC_IS_EXPIRED", "DOC_EXPIRED_DATE", "DOC_ACL_ID", "DOC_STATUS", "DOC_LOCATION", "DOC_CREATOR_ID", "DOC_CREATOR_NAME", "DOC_CREATED_DATE", "DOC_UPDATER_ID", "DOC_UPDATER_NAME", "DOC_UPDATED_DATE", "DOC_DELETER_ID", "DOC_DELETER_NAME", "DOC_DELETED_DATE", "DOC_START_PREVENTION_DATE", "DOC_END_PREVENTION_DATE", "DOC_STANDARD", "DOC_ORIGINAL_CREATOR", "DOC_ORIGINAL_BILL_DIVISION", "DOC_EXPIRATION_DATE", "DOC_LASTCHUNKSAVED", "DOC_CHECKINDURINGUNLOCK", "DOC_CHECKEDOUT", "DOC_AUTOVERSION", "DOC_CHECKINONFILECOMPLETE", "DOC_VERSIONCONTROLLED", "DOC_CONTENTTYPE", "DOC_CHANGENOTES", "DOC_CODE", "FILE_ID", "FILE_NAME", "FILE_EXTENSION", "FILE_CONTENT_SIZE", "FILE_CONTENT_HASH", "FILE_CONTENT_IS_ENCRYPTED", "FILE_REPOSITORY_NAME", "FILE_REPOSITORY_WORKSPACE", "FILE_REPOSITORY_PATH", "FILE_CREATOR_ID", "FILE_CREATOR_NAME", "FILE_CREATED_DATE", "FILE_IS_ORIGIN", "FILE_SERIALNUMBER", "FILE_DESCRIPTION", "FILE_UPDATER_ID", "FILE_UPDATED_DATE", "ITEM_INDEX", "LINKED_DATE", "PREV_FILE_ID", "SECURITY_LEVEL", "SECURITY_LEVEL_NM", "DOC_CREATOR_GROUP_ID") AS
SELECT X.DOC_SERIES_ID, X.FOLDER_ID, X.MAP_ID, X.MAP_NAME, X.FOLDER_PATH, X.PROJECT_ID,
       X.DOC_ID, X.DOC_NAME, X.DOC_TYPE_ID, X.DOC_TYPE_NAME, X.DOC_FILE_COUNT, X.DOC_ROOT_ID,
       X.DOC_STEM_ID, X.DOC_IS_CURRENT, X.DOC_VERSION_NUMBER,
       X.DOC_VERSION_NOTE, X.DOC_DESCRIPTION, X.DOC_IS_LOCKED,
       X.DOC_LOCK_OWNER_ID, X.DOC_LOCK_OWNER_NAME, X.DOC_LOCKED_DATE,
       X.DOC_RETENTION, X.DOC_IS_EXPIRED, X.DOC_EXPIRED_DATE,
       X.DOC_ACL_ID, X.DOC_STATUS, X.DOC_LOCATION, X.DOC_CREATOR_ID,
       X.DOC_CREATOR_NAME, X.DOC_CREATED_DATE, X.DOC_UPDATER_ID,
       X.DOC_UPDATER_NAME, X.DOC_UPDATED_DATE, X.DOC_DELETER_ID,
       X.DOC_DELETER_NAME, X.DOC_DELETED_DATE,
       X.DOC_START_PREVENTION_DATE, X.DOC_END_PREVENTION_DATE,
       X.DOC_STANDARD, X.DOC_ORIGINAL_CREATOR,
       X.DOC_ORIGINAL_BILL_DIVISION, X.DOC_EXPIRATION_DATE,
       X.DOC_LASTCHUNKSAVED, X.DOC_CHECKINDURINGUNLOCK,
       X.DOC_CHECKEDOUT, X.DOC_AUTOVERSION,
       X.DOC_CHECKINONFILECOMPLETE, X.DOC_VERSIONCONTROLLED,
       X.DOC_CONTENTTYPE, X.DOC_CHANGENOTES, X.DOC_CODE,
       X.FILE_ID, X.FILE_NAME, X.FILE_EXTENSION, X.FILE_CONTENT_SIZE,
       X.FILE_CONTENT_HASH, X.FILE_CONTENT_IS_ENCRYPTED,
       X.FILE_REPOSITORY_NAME, X.FILE_REPOSITORY_WORKSPACE,
       X.FILE_REPOSITORY_PATH, X.FILE_CREATOR_ID, X.FILE_CREATOR_NAME,
       X.FILE_CREATED_DATE, X.FILE_IS_ORIGIN, X.FILE_SERIALNUMBER,
       X.FILE_DESCRIPTION, X.FILE_UPDATER_ID, X.FILE_UPDATED_DATE,
       X.ITEM_INDEX, X.LINKED_DATE, X.PREV_FILE_ID,
       X.SECURITY_LEVEL, X.SECURITY_LEVEL_NM, X.DOC_CREATOR_GROUP_ID
FROM V_FILES X
WHERE X.PREVENTION_YN = 'N';

COMMENT ON TABLE METAECM.V_ECM_FILES IS '세 영역 폴더에 든 현재 버전 문서의 첨부 파일. 첨부 하나당 한 행. 키는 DOC_SERIES_ID와 FILE_ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_SERIES_ID IS '문서 키. 문서 첫 버전의 DOC_ID(NVL(ROOT_ID, DOC_ID))로 새 버전이 올라와도 그대로다';
COMMENT ON COLUMN METAECM.V_ECM_FILES.FOLDER_ID IS '문서가 든 폴더 ID(FW_FOLDER_DOCUMENT_LINKS.FOLDER_ID)';
COMMENT ON COLUMN METAECM.V_ECM_FILES.MAP_ID IS '문서가 든 폴더의 맵 ID(FW_FOLDERS.MAP_ID): SHARED 전사문서, DEPT 부서문서, PROJECT 프로젝트';
COMMENT ON COLUMN METAECM.V_ECM_FILES.MAP_NAME IS '영역 이름(FW_MAPS.NAME): 전사문서, 부서문서, 프로젝트';
COMMENT ON COLUMN METAECM.V_ECM_FILES.FOLDER_PATH IS '맨 위 폴더부터 이 폴더까지 폴더 이름을 /로 이은 경로. 이름이 빈 폴더는 폴더 ID를 쓴다. 온전한 경로가 1,000자 이상이면 이 폴더에 가까운 32단계만 이름마다 앞 30자씩 잇는다';
COMMENT ON COLUMN METAECM.V_ECM_FILES.PROJECT_ID IS '속한 프로젝트 ID. 이 폴더나 그 위에서 확정 프로젝트의 루트 폴더를 찾는다. 그중 가장 가까운 루트 폴더를 가진 프로젝트의 FW_PROJECTS.PROJECT_ID이고 여럿이면 가장 작은 ID다. 없으면 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_ID IS 'FW_DOCUMENTS.DOC_ID: 문서 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_NAME IS 'FW_DOCUMENTS.NAME: 문서명';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_TYPE_ID IS 'FW_DOCUMENTS.DOC_TYPE_ID: 문서유형 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_TYPE_NAME IS 'FW_DOCUMENTS.DOC_TYPE_NAME: 문서유형명';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_FILE_COUNT IS 'FW_DOCUMENTS.FILE_COUNT: 첨부 수';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_ROOT_ID IS 'FW_DOCUMENTS.ROOT_ID: 루트버전 문서 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_STEM_ID IS 'FW_DOCUMENTS.STEM_ID: 줄기버전 문서 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_IS_CURRENT IS 'FW_DOCUMENTS.IS_CURRENT: 최신 여부';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_VERSION_NUMBER IS 'FW_DOCUMENTS.VERSION_NUMBER: 버전';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_VERSION_NOTE IS 'FW_DOCUMENTS.VERSION_NOTE: 버전 노트';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_DESCRIPTION IS 'FW_DOCUMENTS.DESCRIPTION: 문서 설명';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_IS_LOCKED IS 'FW_DOCUMENTS.IS_LOCKED: 잠금 여부';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_LOCK_OWNER_ID IS 'FW_DOCUMENTS.LOCK_OWNER_ID: 잠금 사용자';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_LOCK_OWNER_NAME IS 'FW_DOCUMENTS.LOCK_OWNER_NAME: 잠금 사용자명';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_LOCKED_DATE IS 'FW_DOCUMENTS.LOCKED_DATE: 잠금 날짜';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_RETENTION IS 'FW_DOCUMENTS.RETENTION: 보존연한';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_IS_EXPIRED IS 'FW_DOCUMENTS.IS_EXPIRED: 만기 여부';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_EXPIRED_DATE IS 'FW_DOCUMENTS.EXPIRED_DATE: 만기일';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_ACL_ID IS 'FW_DOCUMENTS.ACL_ID: 권한 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_STATUS IS 'FW_DOCUMENTS.STATUS: 문서 상태';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_LOCATION IS 'FW_DOCUMENTS.LOCATION: 위치';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_CREATOR_ID IS 'FW_DOCUMENTS.CREATOR_ID: 등록자 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_CREATOR_NAME IS 'FW_DOCUMENTS.CREATOR_NAME: 등록자명';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_CREATED_DATE IS 'FW_DOCUMENTS.CREATED_DATE: 등록일';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_UPDATER_ID IS 'FW_DOCUMENTS.UPDATER_ID: 수정자 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_UPDATER_NAME IS 'FW_DOCUMENTS.UPDATER_NAME: 수정자명';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_UPDATED_DATE IS 'FW_DOCUMENTS.UPDATED_DATE: 수정일';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_DELETER_ID IS 'FW_DOCUMENTS.DELETER_ID: 삭제자 ID';
COMMENT ON COLUMN METAECM.V_ECM_FILES.DOC_DELETER_NAME IS 'FW_DOCUMENTS.DELETER_NAME: 삭제자명';
