-- METAECM.V_ECM_FOLDERS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_FOLDERS" ("FOLDER_ID", "NAME", "NAME_EN", "NAME_CN", "PARENT_ID", "ITEM_INDEX", "TYPE", "STATUS", "MAP_ID", "ACL_ID", "CREATOR_ID", "CREATOR_NAME", "CREATED_DATE", "IS_IN_SHARE", "SERIALNUMBER", "LASTCHUNKSAVED", "PARENT_ID_RESOLVED", "PROJECT_YN", "WEBDAV_PARENT_ID", "VERSIONCONTROLLED", "CHECKINDURINGUNLOCK", "CHECKEDOUT", "CHECKINONFILECOMPLETE", "AUTOVERSION", "CONTENTTYPE", "CHANGENOTES", "DESCRIPTION", "UPDATED_DATE", "EXPIRED_DATE", "FOLDER_PATH", "MAP_NAME", "PROJECT_ID", "FOLDER_COUNT", "FILE_COUNT") AS
SELECT F.FOLDER_ID, F.NAME, F.NAME_EN, F.NAME_CN, F.PARENT_ID, F.ITEM_INDEX, F.TYPE, F.STATUS, F.MAP_ID, F.ACL_ID,
       F.CREATOR_ID, F.CREATOR_NAME, F.CREATED_DATE, F.IS_IN_SHARE, F.SERIALNUMBER, F.LASTCHUNKSAVED, F.PARENT_ID_RESOLVED,
       F.PROJECT_YN, F.WEBDAV_PARENT_ID, F.VERSIONCONTROLLED, F.CHECKINDURINGUNLOCK, F.CHECKEDOUT, F.CHECKINONFILECOMPLETE,
       F.AUTOVERSION, F.CONTENTTYPE, F.CHANGENOTES, F.DESCRIPTION, F.UPDATED_DATE, F.EXPIRED_DATE,
       X.FOLDER_PATH, M.NAME AS MAP_NAME, X.PROJECT_ID, S.FOLDER_COUNT, S.FILE_COUNT
FROM V_FOLDERS X
         JOIN FW_FOLDERS F ON F.FOLDER_ID = X.FOLDER_ID
         LEFT JOIN FW_MAPS M ON M.MAP_ID = F.MAP_ID AND M.TYPE = 'FOLDER'
         LEFT JOIN FW_FOLDER_STATISTICS S ON S.FOLDER_ID = F.FOLDER_ID
WHERE X.VISIBLE_YN = 'Y';

COMMENT ON TABLE METAECM.V_ECM_FOLDERS IS '세 영역(전사문서, 부서문서, 프로젝트)의 폴더. 폴더 하나당 한 행. 키는 FOLDER_ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.FOLDER_ID IS 'FW_FOLDERS.FOLDER_ID: 폴더 ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.NAME IS 'FW_FOLDERS.NAME: 폴더명';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.NAME_EN IS 'FW_FOLDERS.NAME_EN: 폴더명_영어';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.NAME_CN IS 'FW_FOLDERS.NAME_CN: 폴더명_중국어';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.PARENT_ID IS 'FW_FOLDERS.PARENT_ID: 상위 폴더 ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.ITEM_INDEX IS 'FW_FOLDERS.ITEM_INDEX: 정렬 순서';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS."TYPE" IS 'FW_FOLDERS.TYPE: 유형';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.STATUS IS 'FW_FOLDERS.STATUS: 폴더 상태';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.MAP_ID IS 'FW_FOLDERS.MAP_ID: 맵 ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.ACL_ID IS 'FW_FOLDERS.ACL_ID: 권한 ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CREATOR_ID IS 'FW_FOLDERS.CREATOR_ID: 등록자 ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CREATOR_NAME IS 'FW_FOLDERS.CREATOR_NAME: 등록자명';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CREATED_DATE IS 'FW_FOLDERS.CREATED_DATE: 등록일';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.IS_IN_SHARE IS 'FW_FOLDERS.IS_IN_SHARE: 사내 공용 폴더 여부';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.SERIALNUMBER IS 'FW_FOLDERS.SERIALNUMBER: 일련번호';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.LASTCHUNKSAVED IS 'FW_FOLDERS.LASTCHUNKSAVED: 마지막 청크 저장';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.PARENT_ID_RESOLVED IS 'FW_FOLDERS.PARENT_ID_RESOLVED: 상위 ID(확정)';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.PROJECT_YN IS 'FW_FOLDERS.PROJECT_YN: 프로젝트 여부';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.WEBDAV_PARENT_ID IS 'FW_FOLDERS.WEBDAV_PARENT_ID: WebDAV 상위 ID';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.VERSIONCONTROLLED IS 'FW_FOLDERS.VERSIONCONTROLLED: 버전관리 여부';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CHECKINDURINGUNLOCK IS 'FW_FOLDERS.CHECKINDURINGUNLOCK: 잠금해제 시 체크인';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CHECKEDOUT IS 'FW_FOLDERS.CHECKEDOUT: 체크아웃 여부';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CHECKINONFILECOMPLETE IS 'FW_FOLDERS.CHECKINONFILECOMPLETE: 파일 완료 시 체크인';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.AUTOVERSION IS 'FW_FOLDERS.AUTOVERSION: 자동 버전 여부';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CONTENTTYPE IS 'FW_FOLDERS.CONTENTTYPE: 콘텐츠 유형';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.CHANGENOTES IS 'FW_FOLDERS.CHANGENOTES: 변경 메모';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.DESCRIPTION IS 'FW_FOLDERS.DESCRIPTION: 폴더 설명';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.UPDATED_DATE IS 'FW_FOLDERS.UPDATED_DATE: 수정일시';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.EXPIRED_DATE IS 'FW_FOLDERS.EXPIRED_DATE: 만료일';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.FOLDER_PATH IS '맨 위 폴더부터 이 폴더까지 폴더 이름을 /로 이은 경로. 이름이 빈 폴더는 폴더 ID를 쓴다. 온전한 경로가 1,000자 이상이면 이 폴더에 가까운 32단계만 이름마다 앞 30자씩 잇는다';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.MAP_NAME IS '영역 이름(FW_MAPS.NAME): 전사문서, 부서문서, 프로젝트';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.PROJECT_ID IS '속한 프로젝트 ID. 이 폴더나 그 위에서 확정 프로젝트의 루트 폴더를 찾는다. 그중 가장 가까운 루트 폴더를 가진 프로젝트의 FW_PROJECTS.PROJECT_ID이고 여럿이면 가장 작은 ID다. 없으면 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.FOLDER_COUNT IS 'FW_FOLDER_STATISTICS.FOLDER_COUNT: 자기 자신을 제외한 모든 활성 하위 폴더 수(빈 폴더 포함). 마지막 성공 배치 집계값이며 아직 집계되지 않은 폴더는 NULL이다';
COMMENT ON COLUMN METAECM.V_ECM_FOLDERS.FILE_COUNT IS 'FW_FOLDER_STATISTICS.FILE_COUNT: 현재 폴더 및 활성 하위 폴더에서 현재 버전 활성 문서에 연결된 중복 제거 파일 수. 마지막 성공 배치 집계값이며 아직 집계되지 않은 폴더는 NULL이다';


-- METAECM.V_ECM_GROUPS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_GROUPS" ("GROUP_ID", "NAME", "PARENT_ID", "STATUS", "CORP_CD") AS
SELECT G.GROUP_ID, G.NAME, G.PARENT_ID, G.STATUS, G.CORP_CD
FROM FW_GROUPS G;

COMMENT ON TABLE METAECM.V_ECM_GROUPS IS '부서. 부서 하나당 한 행. 키는 GROUP_ID';
COMMENT ON COLUMN METAECM.V_ECM_GROUPS.GROUP_ID IS '부서 ID(FW_GROUPS.GROUP_ID)';
COMMENT ON COLUMN METAECM.V_ECM_GROUPS.NAME IS '부서 이름(FW_GROUPS.NAME). 인사 연동이 폐지한 부서는 이름 끝에 [부서 ID]가 붙는다';
COMMENT ON COLUMN METAECM.V_ECM_GROUPS.PARENT_ID IS '상위 부서 ID(FW_GROUPS.PARENT_ID). 맨 위 부서는 N이다';
COMMENT ON COLUMN METAECM.V_ECM_GROUPS.STATUS IS '부서 상태(FW_GROUPS.STATUS): CREATED, UPDATED, DELETED. 인사 연동은 폐지한 부서를 퇴직부서 아래로 옮기고 UPDATED로 둔다';
COMMENT ON COLUMN METAECM.V_ECM_GROUPS.CORP_CD IS 'FW_GROUPS.CORP_CD: 회사 코드';


