, "SCOPECMC6_NM", "SCOPECMC6ETC", "SCOPECMC7", "SCOPECMC7_NM", "SCOPECMC7ETC", "SCOPECMD", "SCOPECMD1", "SCOPECMD1_NM", "SCOPECMD1ETC", "SCOPECMD2", "SCOPECMD2_NM", "SCOPECMD2ETC", "SCOPECMD3", "SCOPECMD3_NM", "SCOPECMD3ETC", "SCOPECMD4", "SCOPECMD4_NM", "SCOPECMD4ETC", "SCOPECMD5", "SCOPECMD5_NM", "SCOPECMD5ETC", "MATERIAL", "MATERIALTYPEA", "MATERIALTYPEA_NM", "MATERIALTYPEAETC", "INNERPART", "DEPARTMENTPMID", "DEPARTMENTPMNM", "GENERALMANAGERID", "GENERALMANAGERNM", "OUTERPART", "CONSUMER", "CONTRACTORDERER", "ADMITTER", "INSPECTOR", "CONSTRUCTIONPM", "PROJECTOPERATOR", "DESIGNER", "BUILDER", "CONSULTING", "REGIONLEVEL1ETC", "ZONELEVEL1ETC", "AREALEVEL1ETC", "USEETCLEVEL1ETC", "DESIGNINFO", "TRANSFERSTATUS", "TRANSFERSTATUS_NM", "SITEGUBUN1", "SITEGUBUN1_NM", "PROJECTGUBUN2", "PROJECTGUBUN2_NM", "SITEGUBUN2", "SITEGUBUN2_NM", "PROJECTGUBUN2TITLE", "SITEOPENYN", "ORDERDEPT", "WORKGUBUN", "WORKGUBUN_NM", "SERVICEGUBUN", "SERVICEGUBUN_NM", "PARTICIPATIONSTEP", "PARTICIPATIONSTEP_NM", "SALESPMNM", "SALESPANM", "OPERATIONPANM", "ORIGINALORDERER", "JOINTCONTRACTOR", "EXTERNALETC", "LOCATIONGUBUN", "LOCATIONGUBUN_NM", "BASECURRENCY", "BASECURRENCY_NM", "PRETRANSFER_DATE", "PROJECTEND_DATE", "ZEROENERGYEVALMETHOD", "ZEROENERGYEVALMETHOD_NM", "BFCERTIFICATIONPC", "BFCERTIFICATIONPC_NM", "IBCERTIFICATIONPC", "IBCERTIFICATIONPC_NM", "LEEDVERSION", "LEEDVERSION_NM", "ECOHOUSECERT", "ECOHOUSECERT_NM", "HEALTHFRIENDLYTYPE", "HEALTHFRIENDLYTYPE_NM", "EDUSAFETYCERT", "EDUSAFETYCERT_NM", "ETCINFOGUBUN", "ETCINFOGUBUN_NM", "MATERIALTECHCIVIL", "MATERIALTECHCIVIL_NM", "MATERIALTECHMACHINE", "MATERIALTECHMACHINE_NM", "MATERIALTECHELECTRIC", "MATERIALTECHELECTRIC_NM", "MATERIALTECHFIRE", "MATERIALTECHFIRE_NM", "SMARTCONSTRUCTIONTECH", "SMARTCONSTRUCTIONTECH_NM", "PROJECTGUBUNTITLE", "EXCHANGERATE", "EXCHANGEDATE", "PRETRANSFERYN1", "PRETRANSFERYN1_NM", "PRETRANSFERYN2", "PRETRANSFERYN2_NM", "EDUSAFETYINDOOR", "EDUSAFETYINDOOR_NM", "EDUSAFETYOUTDOOR", "EDUSAFETYOUTDOOR_NM", "OPERATIONPMNM", "SALESPMID", "SALESPAID", "OPERATIONPMID", "OPERATIONPAID", "DATACENTERCAPACITY", "WITHDRAWPLAN_DATE1", "WITHDRAWPLAN_DATE2", "SMARTLOGISTICSK", "SMARTLOGISTICSK_NM", "SMARTLOGISTICSPC", "SMARTLOGISTICSPC_NM", "SMARTLOGISTICSMC", "SMARTLOGISTICSMC_NM", "ROOT_FOLDER_YN") AS
SELECT P.PROJECT_ID,
       P.LEGACY_PROJECT_ID,
       P.FOLDER_ID,
       P.CREATOR_ID,
       P.CREATOR_INFO_ID,
       P.MANAGER_GROUP_ID,
       P.ACL_ID,
       P.ACL_LEVEL_ID,
       P.CREATED_DATE,
       P.LAST_MODIFIED_DATE,
       P.EXPIRED_DATE,
       P.PROJECTSTATUS,
       P.TRANSFEREDDEGREE,
       P.REPRESENTPORTLETDATE,
       P.SAVE_STATUS,
       I.PROJECT_INFO_ID,
       I.BUSINESSINFO,
       CASE WHEN U.PROJECTNO = 'Y' THEN I.PROJECTNO END AS PROJECTNO,
       I.PJTNAME,
       CASE WHEN U.MISNAME = 'Y' THEN I.MISNAME END AS MISNAME,
       CASE WHEN U.MISNAMEENG = 'Y' THEN I.MISNAMEENG END AS MISNAMEENG,
       CASE WHEN U.CONTRACTNAME = 'Y' THEN I.CONTRACTNAME END AS CONTRACTNAME,
       CASE WHEN U.CONTRACTNAMEENG = 'Y' THEN I.CONTRACTNAMEENG END AS CONTRACTNAMEENG,
       CASE WHEN U.NAME = 'Y' THEN I.NAME END AS NAME,
       CASE WHEN U.NAMEENG = 'Y' THEN I.NAMEENG END AS NAMEENG,
       CASE WHEN U.SUBPROJECTNO = 'Y' THEN I.SUBPROJECTNO END AS SUBPROJECTNO,
       CASE WHEN U.SUBMISNAME = 'Y' THEN I.SUBMISNAME END AS SUBMISNAME,
       CASE WHEN U.SECURITYLEVEL = 'Y' THEN I.SECURITYLEVEL END AS SECURITYLEVEL,
       CASE WHEN U.SECURITYLEVEL = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.SECURITYLEVEL || '|', '|' || C.CODE || '|'))
FROM FW_CODE C
WHERE C.CODE_ID = 'SECURITYLEVEL' AND C.PARENT_ID IS NULL
  AND INSTR('|' || I.SECURITYLEVEL || '|', '|' || C.CODE || '|') > 0) END AS SECURITYLEVEL_NM,
       CASE WHEN U.PROJECTGUBUN = 'Y' THEN I.PROJECTGUBUN END AS PROJECTGUBUN,
       CASE WHEN U.PROJECTGUBUN = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.PROJECTGUBUN || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'PROJECTGUBUN' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.PROJECTGUBUN || '|', '|' || C.CODE || '|') > 0) END AS PROJECTGUBUN_NM,
       I.POSITION,
       I.COUNTRY,
       I.CBEFORECOMPLETED,
       CASE WHEN U.CITYBEFORE = 'Y' THEN I.CITYBEFORE END AS CITYBEFORE,
       CASE WHEN U.CITYBEFORE = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.CITYBEFORE || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'CITYBEFORE' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.CITYBEFORE || '|', '|' || C.CODE || '|') > 0) END AS CITYBEFORE_NM,
       CASE WHEN U.TOWNBEFORE = 'Y' THEN I.TOWNBEFORE END AS TOWNBEFORE,
       CASE WHEN U.TOWNBEFORE = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.TOWNBEFORE || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE ((C.CODE_ID = 'TOWNBEFORE' AND C.PARENT_ID IS NULL) OR (C.PARENT_ID IS NOT NULL AND REGEXP_REPLACE(C.CODE_ID, '_[0-9]+$', '') = 'TOWNBEFORE'))
                                  AND NOT EXISTS (SELECT 1 FROM FW_CODE C2 WHERE ((C2.CODE_ID = 'TOWNBEFORE' AND C2.PARENT_ID IS NULL) OR (C2.PARENT_ID IS NOT NULL AND REGEXP_REPLACE(C2.CODE_ID, '_[0-9]+$', '') = 'TOWNBEFORE')) AND C2.CODE = C.CODE
                                                   AND (CASE WHEN C2.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C2.PARENT_ID), '_[0-9]+$', '') = 'CITYBEFORE' AND INSTR('|' || I.CITYBEFORE || '|', '|' || TRIM(C2.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END > CASE WHEN C.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C.PARENT_ID), '_[0-9]+$', '') = 'CITYBEFORE' AND INSTR('|' || I.CITYBEFORE || '|', '|' || TRIM(C.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END OR (CASE WHEN C2.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C2.PARENT_ID), '_[0-9]+$', '') = 'CITYBEFORE' AND INSTR('|' || I.CITYBEFORE || '|', '|' || TRIM(C2.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END = CASE WHEN C.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C.PARENT_ID), '_[0-9]+$', '') = 'CITYBEFORE' AND INSTR('|' || I.CITYBEFORE || '|', '|' || TRIM(C.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END AND (C2.CODE_ID < C.CODE_ID OR (C2.CODE_ID = C.CODE_ID AND NVL(C2.SORT_ORDER, 1E9) < NVL(C.SORT_ORDER, 1E9))))))
                                  AND INSTR('|' || I.TOWNBEFORE || '|', '|' || C.CODE || '|') > 0) END AS TOWNBEFORE_NM,
       CASE WHEN U.DETAILEDADDRESSBEFORE = 'Y' THEN I.DETAILEDADDRESSBEFORE END AS DETAILEDADDRESSBEFORE,
       I.CAFTERCOMPLETED,
       CASE WHEN U.CITYAFTER = 'Y' THEN I.CITYAFTER END AS CITYAFTER,
       CASE WHEN U.CITYAFTER = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.CITYAFTER || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'CITYAFTER' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.CITYAFTER || '|', '|' || C.CODE || '|') > 0) END AS CITYAFTER_NM,
       CASE WHEN U.TOWNAFTER = 'Y' THEN I.TOWNAFTER END AS TOWNAFTER,
       CASE WHEN U.TOWNAFTER = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.TOWNAFTER || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE ((C.CODE_ID = 'TOWNAFTER' AND C.PARENT_ID IS NULL) OR (C.PARENT_ID IS NOT NULL AND REGEXP_REPLACE(C.CODE_ID, '_[0-9]+$', '') = 'TOWNAFTER'))
                                  AND NOT EXISTS (SELECT 1 FROM FW_CODE C2 WHERE ((C2.CODE_ID = 'TOWNAFTER' AND C2.PARENT_ID IS NULL) OR (C2.PARENT_ID IS NOT NULL AND REGEXP_REPLACE(C2.CODE_ID, '_[0-9]+$', '') = 'TOWNAFTER')) AND C2.CODE = C.CODE
                                                   AND (CASE WHEN C2.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C2.PARENT_ID), '_[0-9]+$', '') = 'CITYAFTER' AND INSTR('|' || I.CITYAFTER || '|', '|' || TRIM(C2.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END > CASE WHEN C.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C.PARENT_ID), '_[0-9]+$', '') = 'CITYAFTER' AND INSTR('|' || I.CITYAFTER || '|', '|' || TRIM(C.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END OR (CASE WHEN C2.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C2.PARENT_ID), '_[0-9]+$', '') = 'CITYAFTER' AND INSTR('|' || I.CITYAFTER || '|', '|' || TRIM(C2.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END = CASE WHEN C.PARENT_CODE IS NOT NULL AND ((REGEXP_REPLACE(TRIM(C.PARENT_ID), '_[0-9]+$', '') = 'CITYAFTER' AND INSTR('|' || I.CITYAFTER || '|', '|' || TRIM(C.PARENT_CODE) || '|') > 0)) THEN 1 ELSE 0 END AND (C2.CODE_ID < C.CODE_ID OR (C2.CODE_ID = C.CODE_ID AND NVL(C2.SORT_ORDER, 1E9) < NVL(C.SORT_ORDER, 1E9))))))
                                  AND INSTR('|' || I.TOWNAFTER || '|', '|' || C.CODE || '|') > 0) END AS TOWNAFTER_NM,
       CASE WHEN U.DETAILEDADDRESSAFTER = 'Y' THEN I.DETAILEDADDRESSAFTER END AS DETAILEDADDRESSAFTER,
       I.OVERSEAS,
       I.OBEFORECOMPLETED,
       CASE WHEN U.NATIONBEFORE = 'Y' THEN I.NATIONBEFORE END AS NATIONBEFORE,
       CASE WHEN U.NATIONBEFORE = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.NATIONBEFORE || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'NATIONBEFORE' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.NATIONBEFORE || '|', '|' || C.CODE || '|') > 0) END AS NATIONBEFORE_NM,
       CASE WHEN U.NATIONDETAILEDADDRESSBEFORE = 'Y' THEN I.NATIONDETAILEDADDRESSBEFORE END AS NATIONDETAILEDADDRESSBEFORE,
       I.OAFTERCOMPLETED,
       CASE WHEN U.NATIONAFTER = 'Y' THEN I.NATIONAFTER END AS NATIONAFTER,
       CASE WHEN U.NATIONAFTER = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.NATIONAFTER || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'NATIONAFTER' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.NATIONAFTER || '|', '|' || C.CODE || '|') > 0) END AS NATIONAFTER_NM,
       CASE WHEN U.NATIONDETAILEDADDRESSAFTER = 'Y' THEN I.NATIONDETAILEDADDRESSAFTER END AS NATIONDETAILEDADDRESSAFTER,
       I.ENTERPRISETYPE,
       CASE WHEN U.DIVISIONBUSINESS1 = 'Y' THEN I.DIVISIONBUSINESS1 END AS DIVISIONBUSINESS1,
       CASE WHEN U.DIVISIONBUSINESS1 = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.DIVISIONBUSINESS1 || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'DIVISIONBUSINESS1' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.DIVISIONBUSINESS1 || '|', '|' || C.CODE || '|') > 0) END AS DIVISIONBUSINESS1_NM,
       CASE WHEN U.DIVISIONBUSINESS2 = 'Y' THEN I.DIVISIONBUSINESS2 END AS DIVISIONBUSINESS2,
       CASE WHEN U.DIVISIONBUSINESS2 = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.DIVISIONBUSINESS2 || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'DIVISIONBUSINESS2' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.DIVISIONBUSINESS2 || '|', '|' || C.CODE || '|') > 0) END AS DIVISIONBUSINESS2_NM,
       CASE WHEN U.DIVISIONBUSINESS2ETC = 'Y' THEN I.DIVISIONBUSINESS2ETC END AS DIVISIONBUSINESS2ETC,
       CASE WHEN U.DIVISIONBUSINESS3 = 'Y' THEN I.DIVISIONBUSINESS3 END AS DIVISIONBUSINESS3,
       CASE WHEN U.DIVISIONBUSINESS3 = 'Y' THEN (SELECT LISTAGG(C.CODE_NM, ', ') WITHIN GROUP (ORDER BY INSTR('|' || I.DIVISIONBUSINESS3 || '|', '|' || C.CODE || '|'))
                                 FROM FW_CODE C
                                WHERE C.CODE_ID = 'DIVISIONBUSINESS3' AND C.PARENT_ID IS NULL
                                  AND INSTR('|' || I.DIVISIONBUSINESS3 || '|', '|' || C.CODE || '|') > 0) END AS DIVISIONBUSINESS3_NM,
       CASE WHEN U.DIVISIONBUSINESS3ETC = 'Y' THEN I.DIVISIONBUSINESS3ETC END AS DIVISIONBUSINESS3ETC,
       I.BUSINESSEXPENSES,
