JOIN FW_PROJECT_INFO I ON I.PROJECT_INFO_ID = P.PROJECT_ID
CROSS JOIN (SELECT MAX(CASE WHEN L.FIELD_NAME = 'PROJECTNO' THEN L.USE_YN END) AS PROJECTNO,
                   MAX(CASE WHEN L.FIELD_NAME = 'MISNAME' THEN L.USE_YN END) AS MISNAME,
                   MAX(CASE WHEN L.FIELD_NAME = 'MISNAMEENG' THEN L.USE_YN END) AS MISNAMEENG,
                   MAX(CASE WHEN L.FIELD_NAME = 'CONTRACTNAME' THEN L.USE_YN END) AS CONTRACTNAME,
                   MAX(CASE WHEN L.FIELD_NAME = 'CONTRACTNAMEENG' THEN L.USE_YN END) AS CONTRACTNAMEENG,
                   MAX(CASE WHEN L.FIELD_NAME = 'NAME' THEN L.USE_YN END) AS NAME,
                   MAX(CASE WHEN L.FIELD_NAME = 'NAMEENG' THEN L.USE_YN END) AS NAMEENG,
                   MAX(CASE WHEN L.FIELD_NAME = 'SUBPROJECTNO' THEN L.USE_YN END) AS SUBPROJECTNO,
                   MAX(CASE WHEN L.FIELD_NAME = 'SUBMISNAME' THEN L.USE_YN END) AS SUBMISNAME,
                   MAX(CASE WHEN L.FIELD_NAME = 'SECURITYLEVEL' THEN L.USE_YN END) AS SECURITYLEVEL,
