                   MAX(CASE WHEN L.FIELD_NAME = 'NATIONBEFORE' THEN L.USE_YN END) AS NATIONBEFORE,
                   MAX(CASE WHEN L.FIELD_NAME = 'NATIONDETAILEDADDRESSBEFORE' THEN L.USE_YN END) AS NATIONDETAILEDADDRESSBEFORE,
                   MAX(CASE WHEN L.FIELD_NAME = 'NATIONAFTER' THEN L.USE_YN END) AS NATIONAFTER,
                   MAX(CASE WHEN L.FIELD_NAME = 'NATIONDETAILEDADDRESSAFTER' THEN L.USE_YN END) AS NATIONDETAILEDADDRESSAFTER,
