                                   FROM FW_CODE C
                                   WHERE C.CODE_ID = 'SCOPECMD2' AND C.PARENT_ID IS NULL
                                     AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SCOPECMD3' THEN (SELECT MIN(C.CODE_NM)
                                   FROM FW_CODE C
                                   WHERE C.CODE_ID = 'SCOPECMD3' AND C.PARENT_ID IS NULL
                                     AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SCOPECMD4' THEN (SELECT MIN(C.CODE_NM)
                                   FROM FW_CODE C
                                   WHERE C.CODE_ID = 'SCOPECMD4' AND C.PARENT_ID IS NULL
                                     AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SCOPECMD5' THEN (SELECT MIN(C.CODE_NM)
                                   FROM FW_CODE C
                                   WHERE C.CODE_ID = 'SCOPECMD5' AND C.PARENT_ID IS NULL
                                     AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'MATERIALTYPEA' THEN (SELECT MIN(C.CODE_NM)
                                       FROM FW_CODE C
                                       WHERE C.CODE_ID = 'MATERIALTYPEA' AND C.PARENT_ID IS NULL
                                         AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'TRANSFERSTATUS' THEN (SELECT MIN(C.CODE_NM)
                                        FROM FW_CODE C
                                        WHERE C.CODE_ID = 'TRANSFERSTATUS' AND C.PARENT_ID IS NULL
                                          AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SITEGUBUN1' THEN (SELECT MIN(C.CODE_NM)
                                    FROM FW_CODE C
                                    WHERE C.CODE_ID = 'SITEGUBUN1' AND C.PARENT_ID IS NULL
                                      AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'PROJECTGUBUN2' THEN (SELECT MIN(C.CODE_NM)
                                       FROM FW_CODE C
                                       WHERE C.CODE_ID = 'PROJECTGUBUN2' AND C.PARENT_ID IS NULL
                                         AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SITEGUBUN2' THEN (SELECT MIN(C.CODE_NM)
                                    FROM FW_CODE C
                                    WHERE C.CODE_ID = 'SITEGUBUN2' AND C.PARENT_ID IS NULL
                                      AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'WORKGUBUN' THEN (SELECT MIN(C.CODE_NM)
                                   FROM FW_CODE C
                                   WHERE C.CODE_ID = 'WORKGUBUN' AND C.PARENT_ID IS NULL
                                     AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SERVICEGUBUN' THEN (SELECT MIN(C.CODE_NM)
                                      FROM FW_CODE C
                                      WHERE C.CODE_ID = 'SERVICEGUBUN' AND C.PARENT_ID IS NULL
                                        AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'PARTICIPATIONSTEP' THEN (SELECT MIN(C.CODE_NM)
                                           FROM FW_CODE C
                                           WHERE C.CODE_ID = 'PARTICIPATIONSTEP' AND C.PARENT_ID IS NULL
                                             AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'LOCATIONGUBUN' THEN (SELECT MIN(C.CODE_NM)
                                       FROM FW_CODE C
                                       WHERE C.CODE_ID = 'LOCATIONGUBUN' AND C.PARENT_ID IS NULL
                                         AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'BASECURRENCY' THEN (SELECT MIN(C.CODE_NM)
                                      FROM FW_CODE C
                                      WHERE C.CODE_ID = 'BASECURRENCY' AND C.PARENT_ID IS NULL
                                        AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'ZEROENERGYEVALMETHOD' THEN (SELECT MIN(C.CODE_NM)
                                              FROM FW_CODE C
                                              WHERE C.CODE_ID = 'ZEROENERGYEVALMETHOD' AND C.PARENT_ID IS NULL
                                                AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'BFCERTIFICATIONPC' THEN (SELECT MIN(C.CODE_NM)
                                           FROM FW_CODE C
                                           WHERE C.CODE_ID = 'BFCERTIFICATIONPC' AND C.PARENT_ID IS NULL
                                             AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'IBCERTIFICATIONPC' THEN (SELECT MIN(C.CODE_NM)
                                           FROM FW_CODE C
                                           WHERE C.CODE_ID = 'IBCERTIFICATIONPC' AND C.PARENT_ID IS NULL
                                             AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'LEEDVERSION' THEN (SELECT MIN(C.CODE_NM)
                                     FROM FW_CODE C
                                     WHERE C.CODE_ID = 'LEEDVERSION' AND C.PARENT_ID IS NULL
                                       AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'ECOHOUSECERT' THEN (SELECT MIN(C.CODE_NM)
                                      FROM FW_CODE C
                                      WHERE C.CODE_ID = 'ECOHOUSECERT' AND C.PARENT_ID IS NULL
                                        AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'HEALTHFRIENDLYTYPE' THEN (SELECT MIN(C.CODE_NM)
                                            FROM FW_CODE C
                                            WHERE C.CODE_ID = 'HEALTHFRIENDLYTYPE' AND C.PARENT_ID IS NULL
                                              AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'EDUSAFETYCERT' THEN (SELECT MIN(C.CODE_NM)
                                       FROM FW_CODE C
                                       WHERE C.CODE_ID = 'EDUSAFETYCERT' AND C.PARENT_ID IS NULL
                                         AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'ETCINFOGUBUN' THEN (SELECT MIN(C.CODE_NM)
                                      FROM FW_CODE C
                                      WHERE C.CODE_ID = 'ETCINFOGUBUN' AND C.PARENT_ID IS NULL
                                        AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'MATERIALTECHCIVIL' THEN (SELECT MIN(C.CODE_NM)
                                           FROM FW_CODE C
                                           WHERE C.CODE_ID = 'MATERIALTECHCIVIL' AND C.PARENT_ID IS NULL
                                             AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'MATERIALTECHMACHINE' THEN (SELECT MIN(C.CODE_NM)
                                             FROM FW_CODE C
                                             WHERE C.CODE_ID = 'MATERIALTECHMACHINE' AND C.PARENT_ID IS NULL
                                               AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'MATERIALTECHELECTRIC' THEN (SELECT MIN(C.CODE_NM)
                                              FROM FW_CODE C
                                              WHERE C.CODE_ID = 'MATERIALTECHELECTRIC' AND C.PARENT_ID IS NULL
                                                AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'MATERIALTECHFIRE' THEN (SELECT MIN(C.CODE_NM)
                                          FROM FW_CODE C
                                          WHERE C.CODE_ID = 'MATERIALTECHFIRE' AND C.PARENT_ID IS NULL
                                            AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SMARTCONSTRUCTIONTECH' THEN (SELECT MIN(C.CODE_NM)
                                               FROM FW_CODE C
                                               WHERE C.CODE_ID = 'SMARTCONSTRUCTIONTECH' AND C.PARENT_ID IS NULL
                                                 AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'PRETRANSFERYN1' THEN (SELECT MIN(C.CODE_NM)
                                        FROM FW_CODE C
                                        WHERE C.CODE_ID = 'PRETRANSFERYN1' AND C.PARENT_ID IS NULL
                                          AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'PRETRANSFERYN2' THEN (SELECT MIN(C.CODE_NM)
                                        FROM FW_CODE C
                                        WHERE C.CODE_ID = 'PRETRANSFERYN2' AND C.PARENT_ID IS NULL
                                          AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'EDUSAFETYINDOOR' THEN (SELECT MIN(C.CODE_NM)
                                         FROM FW_CODE C
                                         WHERE C.CODE_ID = 'EDUSAFETYINDOOR' AND C.PARENT_ID IS NULL
                                           AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'EDUSAFETYOUTDOOR' THEN (SELECT MIN(C.CODE_NM)
                                          FROM FW_CODE C
                                          WHERE C.CODE_ID = 'EDUSAFETYOUTDOOR' AND C.PARENT_ID IS NULL
                                            AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SMARTLOGISTICSK' THEN (SELECT MIN(C.CODE_NM)
                                         FROM FW_CODE C
                                         WHERE C.CODE_ID = 'SMARTLOGISTICSK' AND C.PARENT_ID IS NULL
                                           AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SMARTLOGISTICSPC' THEN (SELECT MIN(C.CODE_NM)
                                          FROM FW_CODE C
                                          WHERE C.CODE_ID = 'SMARTLOGISTICSPC' AND C.PARENT_ID IS NULL
                                            AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           WHEN N'SMARTLOGISTICSMC' THEN (SELECT MIN(C.CODE_NM)
                                          FROM FW_CODE C
                                          WHERE C.CODE_ID = 'SMARTLOGISTICSMC' AND C.PARENT_ID IS NULL
                                            AND C.CODE = TO_CHAR(TRIM(D.PROPERTYVALUE1)))
           END AS PROPERTYVALUE1_NM,
       D.PROPERTYVALUE2, D.PROPERTYVALUE3, D.PROPERTYVALUE4, D.SORTORDER
FROM FW_PROJECT_INFO_DETAILS D
         JOIN FW_PROJECTS P ON P.PROJECT_ID = D.PROJECT_ID
         JOIN FW_PROJECT_INFO I ON I.PROJECT_INFO_ID = D.PROJECT_ID
         LEFT JOIN (SELECT L.FIELD_NAME, MAX(L.USE_YN) AS USE_YN
                    FROM FW_PROJECT_INFO_LAYOUT L
                    WHERE L.FIELD_NAME IS NOT NULL
                    GROUP BY L.FIELD_NAME) Y ON Y.FIELD_NAME = UPPER(D.GUBUN)
WHERE P.SAVE_STATUS = 'C'
  AND (Y.FIELD_NAME IS NULL OR Y.USE_YN = 'Y');

COMMENT ON TABLE METAECM.V_ECM_PROJECT_DETAILS IS '워크시트 칸 밖(FW_PROJECT_INFO_DETAILS)에 저장된 추가 값. 값 하나당 한 행. 키는 PROJECT_INFO_DETAIL_ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROJECT_INFO_DETAIL_ID IS 'FW_PROJECT_INFO_DETAILS.PROJECT_INFO_DETAIL_ID: 프로젝트 상세정보 ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROJECT_ID IS 'FW_PROJECT_INFO_DETAILS.PROJECT_ID: 소속 프로젝트 식별자';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.GUBUN IS 'FW_PROJECT_INFO_DETAILS.GUBUN: 구분';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.FIELD_NAME IS '항목 이름. GUBUN을 대문자로 바꾼 값으로 FW_PROJECT_INFO_LAYOUT.FIELD_NAME과 V_ECM_PROJECTS 컬럼 이름에 맞춘다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROPERTYVALUE1 IS 'FW_PROJECT_INFO_DETAILS.PROPERTYVALUE1: 추가 정보 값1. 항목은 FIELD_NAME으로 구분한다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROPERTYVALUE1_NM IS '값 1(PROPERTYVALUE1) 코드의 이름(FW_CODE.CODE_NM). 코드 항목일 때만 있다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROPERTYVALUE2 IS 'FW_PROJECT_INFO_DETAILS.PROPERTYVALUE2: 추가 정보 값2. 항목은 FIELD_NAME으로 구분한다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROPERTYVALUE3 IS 'FW_PROJECT_INFO_DETAILS.PROPERTYVALUE3: 추가 정보 값3. 항목은 FIELD_NAME으로 구분한다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.PROPERTYVALUE4 IS 'FW_PROJECT_INFO_DETAILS.PROPERTYVALUE4: 추가 정보 값4. 항목은 FIELD_NAME으로 구분한다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_DETAILS.SORTORDER IS 'FW_PROJECT_INFO_DETAILS.SORTORDER: 정렬 순서';


-- METAECM.V_ECM_PROJECT_FIELDS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_PROJECT_FIELDS" ("FIELD_NAME", "LABEL", "COL_TYPE", "INPUT_TYPE", "VIEW_ORDER", "TAB_NAME", "TITLE_PATH") AS
SELECT B.FIELD_NAME, B.LABEL, B.COL_TYPE, B.INPUT_TYPE, B.VIEW_ORDER, B.TITLE1 AS TAB_NAME,
       SUBSTR(CASE WHEN B.TITLE1 IS NOT NULL THEN ' > ' || B.TITLE1 END
                  || CASE WHEN B.TITLE2 IS NOT NULL THEN ' > ' || B.TITLE2 END
                  || CASE WHEN B.TITLE3 IS NOT NULL THEN ' > ' || B.TITLE3 END
                  || CASE WHEN B.TITLE4 IS NOT NULL THEN ' > ' || B.TITLE4 END, 4) AS TITLE_PATH
FROM (SELECT A.FIELD_NAME, A.LABEL, A.COL_TYPE, A.INPUT_TYPE, A.VIEW_ORDER,
             (SELECT MAX(TRIM(T.LABEL)) FROM FW_PROJECT_INFO_LAYOUT T WHERE T.COL_TYPE = 'TITLE1' AND T.VIEW_ORDER = A.T1) AS TITLE1,
             CASE WHEN A.T2 > NVL(A.T1, -1)
                      THEN (SELECT MAX(TRIM(T.LABEL)) FROM FW_PROJECT_INFO_LAYOUT T WHERE T.COL_TYPE = 'TITLE2' AND T.VIEW_ORDER = A.T2) END AS TITLE2,
             CASE WHEN A.T3 > GREATEST(NVL(A.T1, -1), NVL(A.T2, -1))
                      THEN (SELECT MAX(TRIM(T.LABEL)) FROM FW_PROJECT_INFO_LAYOUT T WHERE T.COL_TYPE = 'TITLE3' AND T.VIEW_ORDER = A.T3) END AS TITLE3,
             CASE WHEN A.T4 > GREATEST(NVL(A.T1, -1), NVL(A.T2, -1), NVL(A.T3, -1))
                      THEN (SELECT MAX(TRIM(T.LABEL)) FROM FW_PROJECT_INFO_LAYOUT T WHERE T.COL_TYPE = 'TITLE4' AND T.VIEW_ORDER = A.T4) END AS TITLE4
      FROM (SELECT L.FIELD_NAME, L.LABEL, L.COL_TYPE, L.INPUT_TYPE, L.VIEW_ORDER, L.USE_YN,
                   MAX(CASE WHEN L.COL_TYPE = 'TITLE1' THEN L.VIEW_ORDER END) OVER (ORDER BY L.VIEW_ORDER ROWS UNBOUNDED PRECEDING) AS T1,
                MAX(CASE WHEN L.COL_TYPE = 'TITLE2' THEN L.VIEW_ORDER END) OVER (ORDER BY L.VIEW_ORDER ROWS UNBOUNDED PRECEDING) AS T2,
                MAX(CASE WHEN L.COL_TYPE = 'TITLE3' THEN L.VIEW_ORDER END) OVER (ORDER BY L.VIEW_ORDER ROWS UNBOUNDED PRECEDING) AS T3,
                MAX(CASE WHEN L.COL_TYPE = 'TITLE4' THEN L.VIEW_ORDER END) OVER (ORDER BY L.VIEW_ORDER ROWS UNBOUNDED PRECEDING) AS T4
            FROM FW_PROJECT_INFO_LAYOUT L) A
      WHERE A.FIELD_NAME IS NOT NULL AND A.USE_YN = 'Y') B;

COMMENT ON TABLE METAECM.V_ECM_PROJECT_FIELDS IS '워크시트에서 사용 중인 항목. 항목 하나당 한 행. 키는 FIELD_NAME(V_ECM_PROJECTS 컬럼 이름)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.FIELD_NAME IS 'FW_PROJECT_INFO_LAYOUT.FIELD_NAME: FW_PROJECT_INFO 실제 컬럼명';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.LABEL IS 'FW_PROJECT_INFO_LAYOUT.LABEL: 한글 라벨';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.COL_TYPE IS 'FW_PROJECT_INFO_LAYOUT.COL_TYPE: 항목 유형';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.INPUT_TYPE IS 'FW_PROJECT_INFO_LAYOUT.INPUT_TYPE: 코드 항목 입력 형태 (레거시 INPUTTYPE)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.VIEW_ORDER IS 'FW_PROJECT_INFO_LAYOUT.VIEW_ORDER: 표시 순서';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.TAB_NAME IS '이 항목이 든 워크시트 탭 이름. 레이아웃 순서(VIEW_ORDER)에서 이 항목 위로 가장 가까운 TITLE1 제목이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FIELDS.TITLE_PATH IS '탭부터 이 항목이 든 제목까지 제목 이름(TITLE1~TITLE4)을 '' > ''로 이은 경로. 예: 사업 > 참여정보 > 참여자 > 내부';


-- METAECM.V_ECM_PROJECT_FILES source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_PROJECT_FILES" ("PROJECT_ID", "FOLDER_ID", "KIND", "KIND_NAME", "DOC_ID", "DOC_SERIES_ID", "FILE_ID", "FILE_NAME", "CONTENT_SIZE", "CREATOR_ID", "CREATOR_NAME", "CREATED_DATE", "ACL_ID") AS
SELECT X.PROJECT_ID, X.FOLDER_ID, X.KIND, X.KIND_NAME, X.DOC_ID, X.DOC_SERIES_ID, X.FILE_ID, X.FILE_NAME, X.CONTENT_SIZE,
       X.CREATOR_ID, X.CREATOR_NAME, X.CREATED_DATE, X.ACL_ID
FROM V_PROJECT_FILES X
WHERE X.PREVENTION_YN = 'N';

COMMENT ON TABLE METAECM.V_ECM_PROJECT_FILES IS '상세보기의 대표사진, 문서정보, 자재 파일. 첨부 하나당 한 행. 키는 DOC_SERIES_ID와 FILE_ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.PROJECT_ID IS '프로젝트 ID(FW_PROJECTS.PROJECT_ID)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.FOLDER_ID IS '파일이 든 폴더 ID. 프로젝트 폴더 바로 아래에서 대표사진과 자재를 두는 폴더(999.대표사진&자재)다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.KIND IS '파일 종류: PHOTO 프로젝트 사진, PRE_TRANSFER 사전이관 체크리스트, TRANSFER 이관 체크리스트, SITE_COMPLETION 현장완료보고서, MATERIAL 자재';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.KIND_NAME IS '상세보기에 보이는 파일 종류 이름(프로젝트 사진, 사전이관 체크리스트, 이관 체크리스트, 현장완료보고서, 자재)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.DOC_ID IS 'FW_DOCUMENTS.DOC_ID: 문서 ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.DOC_SERIES_ID IS '문서 키. 문서 첫 버전의 DOC_ID(NVL(ROOT_ID, DOC_ID))로 새 버전이 올라와도 그대로다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.FILE_ID IS 'FW_FILES.FILE_ID: 파일 ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.FILE_NAME IS 'FW_FILES.NAME: 파일명';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.CONTENT_SIZE IS 'FW_FILES.CONTENT_SIZE: 파일 크기';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.CREATOR_ID IS 'FW_DOCUMENTS.CREATOR_ID: 등록자 ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.CREATOR_NAME IS 'FW_DOCUMENTS.CREATOR_NAME: 등록자명';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.CREATED_DATE IS 'FW_DOCUMENTS.CREATED_DATE: 등록일';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_FILES.ACL_ID IS 'FW_DOCUMENTS.ACL_ID: 권한 ID';


-- METAECM.V_ECM_PROJECT_GROUPS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_PROJECT_GROUPS" ("GROUP_ID", "NAME", "PROJECT_ID", "GROUP_TYPE", "PARENT_ID") AS
SELECT G.GROUP_ID, G.NAME, G.PROJECT_ID, G.GROUP_TYPE, G.PARENT_ID
FROM FW_PROJECT_GROUPS G
WHERE NOT EXISTS (SELECT 1 FROM FW_PROJECTS P WHERE P.PROJECT_ID = G.PROJECT_ID AND P.SAVE_STATUS = 'T');

COMMENT ON TABLE METAECM.V_ECM_PROJECT_GROUPS IS '프로젝트 그룹. 그룹 하나당 한 행. 키는 GROUP_ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUPS.GROUP_ID IS '프로젝트 그룹 ID(FW_PROJECT_GROUPS.GROUP_ID). 참여자시트 그룹은 PJ_, 프로젝트번호, 종속 번호, _, 그룹 코드를 이은 값이다. 예: PJ_22164M_T1P';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUPS.NAME IS 'FW_PROJECT_GROUPS.NAME: 그룹명';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUPS.PROJECT_ID IS '속한 프로젝트 ID(FW_PROJECT_GROUPS.PROJECT_ID). 연도별 상위 그룹(ORG)은 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUPS.GROUP_TYPE IS '그룹 종류(FW_PROJECT_GROUPS.GROUP_TYPE): ALIAS 참여자시트 그룹, PROJECT 프로젝트 부모 그룹(pj_로 시작)과 그 아래 이관된 그룹, ORG 연도별 상위 그룹';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUPS.PARENT_ID IS '상위 그룹 ID(FW_PROJECT_GROUPS.PARENT_ID). 참여자시트 그룹은 N이다';


-- METAECM.V_ECM_PROJECT_GROUP_USERS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_PROJECT_GROUP_USERS" ("GROUP_ID", "USER_ID", "CREATED_DATE") AS
SELECT M.GROUP_ID, M.USER_ID, M.CREATED_DATE
FROM FW_PROJECT_GROUP_USERS M
         JOIN V_ECM_PROJECT_GROUPS G ON G.GROUP_ID = M.GROUP_ID;

COMMENT ON TABLE METAECM.V_ECM_PROJECT_GROUP_USERS IS '프로젝트 그룹 멤버. 멤버 한 명당 한 행. 키는 GROUP_ID와 USER_ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUP_USERS.GROUP_ID IS '프로젝트 그룹 ID(V_ECM_PROJECT_GROUPS.GROUP_ID)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUP_USERS.USER_ID IS '멤버의 사용자 ID(FW_PROJECT_GROUP_USERS.USER_ID). 이관된 멤버는 예전 시스템의 ID라 FW_USERS에 없을 수 있다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_GROUP_USERS.CREATED_DATE IS 'FW_PROJECT_GROUP_USERS.CREATED_DATE: 그룹 참여일시';


-- METAECM.V_ECM_PROJECT_MEMBERS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_PROJECT_MEMBERS" ("PROJECT_ID", "GROUP_KEY", "GROUP_LABEL", "GROUP_ID", "GROUP_NAME", "USER_ID", "USER_NAME", "EMP_NO", "GROUP_TITLE", "POSITION", "MANHOUR", "AUTHORITY", "TASK") AS
SELECT M.PROJECT_ID, M.GROUP_KEY, M.GROUP_LABEL, M.GROUP_ID, M.GROUP_NAME, M.USER_ID,
       NVL(M.USER_NAME, (SELECT MAX(PP.USER_NAME) KEEP (DENSE_RANK FIRST ORDER BY PP.SORTORDER, PP.PARTICIPANT_ID)
                         FROM FW_PROJECT_PARTICIPANTS PP WHERE PP.PROJECT_ID = M.PROJECT_ID AND PP.ACCOUNT = M.EMP_NO)) AS USER_NAME,
       M.EMP_NO,
       NVL((SELECT MAX(PP.GROUPTITLE) KEEP (DENSE_RANK FIRST ORDER BY PP.SORTORDER, PP.PARTICIPANT_ID)
            FROM FW_PROJECT_PARTICIPANTS PP WHERE PP.PROJECT_ID = M.PROJECT_ID AND PP.ACCOUNT = M.EMP_NO),
           (SELECT MAX(U.DUTY_NAME) FROM FW_USERS U WHERE U.EMP_NO = TO_CHAR(M.EMP_NO))) AS GROUP_TITLE,
       NVL((SELECT MAX(PP.POSITION) KEEP (DENSE_RANK FIRST ORDER BY PP.SORTORDER, PP.PARTICIPANT_ID)
            FROM FW_PROJECT_PARTICIPANTS PP WHERE PP.PROJECT_ID = M.PROJECT_ID AND PP.ACCOUNT = M.EMP_NO),
           (SELECT MAX(U.POSITION_NAME) FROM FW_USERS U WHERE U.EMP_NO = TO_CHAR(M.EMP_NO))) AS POSITION,
       M.MANHOUR,
       (SELECT MAX(PP.AUTHORITY) KEEP (DENSE_RANK FIRST ORDER BY PP.SORTORDER, PP.PARTICIPANT_ID)
          FROM FW_PROJECT_PARTICIPANTS PP WHERE PP.PROJECT_ID = M.PROJECT_ID AND PP.ACCOUNT = M.EMP_NO) AS AUTHORITY,
       M.TASK
FROM (SELECT P.PROJECT_ID, G.GROUP_KEY, G.GROUP_LABEL, GU.GROUP_ID, PG.NAME AS GROUP_NAME, GU.USER_ID,
    NVL(TO_NCHAR(U.EMP_NO), (SELECT MAX(PP.ACCOUNT) FROM FW_PROJECT_PARTICIPANTS PP WHERE PP.USER_ID = GU.USER_ID)) AS EMP_NO,
    NVL(U.NAME, (SELECT MAX(PP.USER_NAME) FROM FW_PROJECT_PARTICIPANTS PP WHERE PP.USER_ID = GU.USER_ID)) AS USER_NAME,
    GU.MANHOUR, GU.TASK
    FROM FW_PROJECTS P
    JOIN FW_PROJECT_INFO I ON I.PROJECT_INFO_ID = P.PROJECT_ID
    CROSS JOIN (SELECT 'GENERAL' AS GROUP_KEY, 'T0' AS GROUP_CODE, '프로젝트총괄' AS GROUP_LABEL FROM DUAL
    UNION ALL SELECT 'DIRECT1', 'T1P', '직접수행1' FROM DUAL
    UNION ALL SELECT 'DIRECT1_VIEW', 'T1V', '직접수행1 열람' FROM DUAL
    UNION ALL SELECT 'DIRECT2', 'T2P', '직접수행2' FROM DUAL
    UNION ALL SELECT 'DIRECT2_VIEW', 'T2V', '직접수행2 열람' FROM DUAL
    UNION ALL SELECT 'SALES_SUPPORT', 'T3', '영업지원' FROM DUAL
    UNION ALL SELECT 'TECH_SUPPORT', 'T4', '기술지원' FROM DUAL
    UNION ALL SELECT 'OPS_SUPPORT', 'T5', '운영지원' FROM DUAL) G
    JOIN FW_PROJECT_GROUP_USERS GU ON GU.GROUP_ID = TO_CHAR('PJ_' || TRIM(I.PROJECTNO) || TRIM(I.SUBPROJECTNO) || '_' || G.GROUP_CODE)
    JOIN FW_PROJECT_GROUPS PG ON PG.GROUP_ID = GU.GROUP_ID
    LEFT JOIN FW_USERS U ON U.USER_ID = GU.USER_ID
    WHERE P.SAVE_STATUS = 'C') M;

COMMENT ON TABLE METAECM.V_ECM_PROJECT_MEMBERS IS '참여자시트 그룹의 멤버. 멤버 한 명당 한 행. 키는 PROJECT_ID, GROUP_ID, USER_ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.PROJECT_ID IS '프로젝트 ID(FW_PROJECTS.PROJECT_ID)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.GROUP_KEY IS '참여자시트 그룹 키(GENERAL, DIRECT1, DIRECT1_VIEW, DIRECT2, DIRECT2_VIEW, SALES_SUPPORT, TECH_SUPPORT, OPS_SUPPORT)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.GROUP_LABEL IS '참여자시트에 보이는 그룹 이름(프로젝트총괄, 직접수행1, 직접수행1 열람, 직접수행2, 직접수행2 열람, 영업지원, 기술지원, 운영지원)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.GROUP_ID IS '프로젝트 그룹 ID(FW_PROJECT_GROUPS.GROUP_ID). PJ_, 프로젝트번호, 종속 번호(있을 때만), _, 그룹 코드(T0, T1P, T1V, T2P, T2V, T3, T4, T5)를 이은 값이다. 예: PJ_22164M_T1P';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.GROUP_NAME IS '저장된 프로젝트 그룹 이름(FW_PROJECT_GROUPS.NAME)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.USER_ID IS '멤버의 사용자 ID(FW_PROJECT_GROUP_USERS.USER_ID). 이관된 멤버는 예전 시스템의 ID라 FW_USERS에 없을 수 있다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.USER_NAME IS '수행자 이름. FW_USERS.NAME이고 없으면 같은 USER_ID의 참여자 행 이름(FW_PROJECT_PARTICIPANTS.USER_NAME)이다. 그래도 없으면 이 프로젝트 참여자 행의 이름이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.EMP_NO IS '사번. FW_USERS.EMP_NO이고 없으면 같은 USER_ID의 참여자 행 사번(FW_PROJECT_PARTICIPANTS.ACCOUNT)이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.GROUP_TITLE IS '직위. 이 프로젝트 참여자 행(사번이 같고 SORTORDER가 가장 앞선 행)의 GROUPTITLE이고 비면 FW_USERS.DUTY_NAME이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS."POSITION" IS '직무. 이 프로젝트 참여자 행의 POSITION이고 비면 FW_USERS.POSITION_NAME이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.MANHOUR IS 'M/H(FW_PROJECT_GROUP_USERS.MANHOUR). 그룹 멤버마다 저장한 값이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.AUTHORITY IS '권한. 이 프로젝트 참여자 행의 AUTHORITY';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_MEMBERS.TASK IS '수행업무(FW_PROJECT_GROUP_USERS.TASK). 그룹 멤버마다 저장한 값이다';


-- METAECM.V_ECM_PROJECT_RELATIONS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_PROJECT_RELATIONS" ("PROJECT_ID", "RELATED_PROJECT_ID", "RELATED_PROJECTNO", "RELATED_SUBPROJECTNO", "RELATED_PROJECT_NAME", "RELATED_PM_NAME") AS
SELECT R.PROJECT_ID, R.RELATED_PROJECT_ID,
       CASE WHEN NVL(U.PROJECTNO, 'Y') = 'Y' THEN I.PROJECTNO END AS RELATED_PROJECTNO,
       CASE WHEN NVL(U.SUBPROJECTNO, 'Y') = 'Y' THEN I.SUBPROJECTNO END AS RELATED_SUBPROJECTNO,
       COALESCE(CASE WHEN NVL(U.MISNAME, 'Y') = 'Y' THEN I.MISNAME END,
                CASE WHEN NVL(U.NAME, 'Y') = 'Y' THEN I.NAME END,
                CASE WHEN NVL(U.PJTNAME, 'Y') = 'Y' THEN TO_NCHAR(I.PJTNAME) END) AS RELATED_PROJECT_NAME,
       CASE WHEN NVL(U.DEPARTMENTPMNM, 'Y') = 'Y' THEN I.DEPARTMENTPMNM END AS RELATED_PM_NAME
FROM FW_PROJECT_RELATIONS R
         JOIN FW_PROJECTS P ON P.PROJECT_ID = R.PROJECT_ID
         JOIN FW_PROJECTS Q ON Q.PROJECT_ID = R.RELATED_PROJECT_ID
         JOIN FW_PROJECT_INFO I ON I.PROJECT_INFO_ID = R.RELATED_PROJECT_ID
         CROSS JOIN (SELECT MAX(CASE WHEN L.FIELD_NAME = 'PROJECTNO' THEN L.USE_YN END) AS PROJECTNO,
                            MAX(CASE WHEN L.FIELD_NAME = 'SUBPROJECTNO' THEN L.USE_YN END) AS SUBPROJECTNO,
                            MAX(CASE WHEN L.FIELD_NAME = 'MISNAME' THEN L.USE_YN END) AS MISNAME,
                            MAX(CASE WHEN L.FIELD_NAME = 'NAME' THEN L.USE_YN END) AS NAME,
                            MAX(CASE WHEN L.FIELD_NAME = 'PJTNAME' THEN L.USE_YN END) AS PJTNAME,
                            MAX(CASE WHEN L.FIELD_NAME = 'DEPARTMENTPMNM' THEN L.USE_YN END) AS DEPARTMENTPMNM
                     FROM FW_PROJECT_INFO_LAYOUT L) U
WHERE P.SAVE_STATUS = 'C'
  AND Q.SAVE_STATUS = 'C';

COMMENT ON TABLE METAECM.V_ECM_PROJECT_RELATIONS IS '관련 프로젝트. 관련 프로젝트 하나당 한 행. 키는 PROJECT_ID와 RELATED_PROJECT_ID';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_RELATIONS.PROJECT_ID IS 'FW_PROJECT_RELATIONS.PROJECT_ID: 기준 프로젝트';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_RELATIONS.RELATED_PROJECT_ID IS 'FW_PROJECT_RELATIONS.RELATED_PROJECT_ID: 관련 프로젝트';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_RELATIONS.RELATED_PROJECTNO IS '관련 프로젝트의 프로젝트번호(FW_PROJECT_INFO.PROJECTNO)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_RELATIONS.RELATED_SUBPROJECTNO IS '관련 프로젝트의 종속 프로젝트번호(FW_PROJECT_INFO.SUBPROJECTNO)';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_RELATIONS.RELATED_PROJECT_NAME IS '관련 프로젝트 이름. FW_PROJECT_INFO의 MISNAME, NAME, PJTNAME 가운데 값이 있는 첫 칸이다';
COMMENT ON COLUMN METAECM.V_ECM_PROJECT_RELATIONS.RELATED_PM_NAME IS '관련 프로젝트의 PM 이름(FW_PROJECT_INFO.DEPARTMENTPMNM)';


-- METAECM.V_ECM_ROLES source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_ROLES" ("ROLE_ID", "NAME", "IS_SYSTEM") AS
SELECT R.ROLE_ID, R.NAME, R.IS_SYSTEM
FROM FW_ROLES R;

COMMENT ON TABLE METAECM.V_ECM_ROLES IS '역할. 역할 하나당 한 행. 키는 ROLE_ID';
COMMENT ON COLUMN METAECM.V_ECM_ROLES.ROLE_ID IS 'FW_ROLES.ROLE_ID: 롤 ID';
COMMENT ON COLUMN METAECM.V_ECM_ROLES.NAME IS 'FW_ROLES.NAME: 롤명';
COMMENT ON COLUMN METAECM.V_ECM_ROLES.IS_SYSTEM IS 'FW_ROLES.IS_SYSTEM: 시스템 여부';


-- METAECM.V_ECM_ROLE_ITEMS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_ROLE_ITEMS" ("ROLE_ID", "RESOURCE_TYPE", "CAN_BROWSE", "CAN_READ", "CAN_CREATE", "CAN_UPDATE", "CAN_DELETE", "CAN_CANCEL_CHECKOUT", "CAN_CHANGE_PERMISSION") AS
SELECT I.ROLE_ID, I.RESOURCE_TYPE, I.CAN_BROWSE, I.CAN_READ, I.CAN_CREATE, I.CAN_UPDATE, I.CAN_DELETE, I.CAN_CANCEL_CHECKOUT,
       I.CAN_CHANGE_PERMISSION
FROM FW_ROLE_ITEMS I;

COMMENT ON TABLE METAECM.V_ECM_ROLE_ITEMS IS '역할의 권한 설정. 역할마다 대상 종류(문서, 폴더)별 한 행. 키는 ROLE_ID와 RESOURCE_TYPE';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.ROLE_ID IS 'FW_ROLE_ITEMS.ROLE_ID: 롤 ID';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.RESOURCE_TYPE IS '권한을 주는 대상 종류(FW_ROLE_ITEMS.RESOURCE_TYPE): DOCUMENT 문서, FOLDER 폴더';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_BROWSE IS '목록 보기 권한(FW_ROLE_ITEMS.CAN_BROWSE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_READ IS '읽기 권한(FW_ROLE_ITEMS.CAN_READ): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_CREATE IS '만들기 권한(FW_ROLE_ITEMS.CAN_CREATE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_UPDATE IS '수정 권한(FW_ROLE_ITEMS.CAN_UPDATE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_DELETE IS '삭제 권한(FW_ROLE_ITEMS.CAN_DELETE): 1 있음, 0 없음';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_CANCEL_CHECKOUT IS '잠금 풀기 권한(FW_ROLE_ITEMS.CAN_CANCEL_CHECKOUT): 1 있음, 0 없음. 폴더(FOLDER) 줄은 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_ROLE_ITEMS.CAN_CHANGE_PERMISSION IS '권한 변경 권한(FW_ROLE_ITEMS.CAN_CHANGE_PERMISSION): 1 있음, 0 없음';


-- METAECM.V_ECM_SHARES source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_SHARES" ("TARGET_TYPE", "TARGET_ID", "DOC_SERIES_ID", "NAME", "SHARE_USER_ID", "SHARE_USER_NAME", "SHARE_DEPT_ID", "SHARE_DEPT_NAME", "SHARED_USER_ID", "SHARED_USER_NAME", "SHARE_TYPE", "SHARED_IS_ALIAS", "AUTHORITY", "SHARE_DATE", "SUB_FOLDER_SHARE_YN") AS
SELECT 'DOCUMENT' AS TARGET_TYPE, S.DOC_ID AS TARGET_ID, NVL(D.ROOT_ID, D.DOC_ID) AS DOC_SERIES_ID, S.NAME,
       S.SHARE_USER_ID, S.SHARE_USER_NAME, S.SHARE_DEPT_ID, S.SHARE_DEPT_NAME, S.SHARED_USER_ID, S.SHARED_USER_NAME,
       S.SHARE_TYPE, S.SHARED_IS_ALIAS, S.AUTHORITY, S.SHARE_DATE, NULL AS SUB_FOLDER_SHARE_YN
FROM FW_SHARE_DOCUMENTS S
         JOIN FW_DOCUMENTS D ON D.DOC_ID = S.DOC_ID
WHERE EXISTS (SELECT 1 FROM V_DOCUMENTS X
              WHERE X.DOC_SERIES_ID = NVL(D.ROOT_ID, D.DOC_ID) AND X.PREVENTION_YN = 'N'
                AND X.DOC_ID IN (SELECT C.DOC_ID FROM FW_DOCUMENTS C
                                 WHERE C.DOC_ID = NVL(D.ROOT_ID, D.DOC_ID) OR C.ROOT_ID = NVL(D.ROOT_ID, D.DOC_ID)))
UNION ALL
SELECT 'FOLDER' AS TARGET_TYPE, S.FOLDER_ID AS TARGET_ID, NULL AS DOC_SERIES_ID, S.NAME,
       S.SHARE_USER_ID, S.SHARE_USER_NAME, S.SHARE_DEPT_ID, S.SHARE_DEPT_NAME, S.SHARED_USER_ID, S.SHARED_USER_NAME,
       S.SHARE_TYPE, S.SHARED_IS_ALIAS, S.AUTHORITY, S.SHARE_DATE, S.SUB_FOLDER_SHARE_YN
FROM FW_SHARE_FOLDERS S
WHERE EXISTS (SELECT 1 FROM V_ECM_FOLDERS F WHERE F.FOLDER_ID = S.FOLDER_ID);

COMMENT ON TABLE METAECM.V_ECM_SHARES IS '문서와 폴더의 공유(원본 FW_SHARE_DOCUMENTS, FW_SHARE_FOLDERS). 공유 하나당 한 행. 키는 TARGET_TYPE, TARGET_ID, SHARE_USER_ID, SHARED_USER_ID';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.TARGET_TYPE IS '공유한 대상 종류: DOCUMENT 문서, FOLDER 폴더';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.TARGET_ID IS '공유한 문서 ID(FW_SHARE_DOCUMENTS.DOC_ID)나 폴더 ID(FW_SHARE_FOLDERS.FOLDER_ID). 문서는 공유한 때의 버전이라 예전 버전일 수 있다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.DOC_SERIES_ID IS '문서 공유의 문서 키(공유한 문서의 NVL(ROOT_ID, DOC_ID)). V_ECM_FILES의 DOC_SERIES_ID와 같은 값이다. 폴더 공유는 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.NAME IS '공유한 문서나 폴더의 이름. 공유할 때 저장한 값이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARE_USER_ID IS '공유한 사용자 ID';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARE_USER_NAME IS '공유한 사용자 이름. 공유할 때 저장한 값이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARE_DEPT_ID IS '공유한 사용자의 부서 ID. 공유할 때 저장한 값이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARE_DEPT_NAME IS '공유한 사용자의 부서 이름. 공유할 때 저장한 값이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARED_USER_ID IS '공유받은 대상 ID. SHARE_TYPE과 SHARED_IS_ALIAS에 따라 사용자, 부서, 별칭 ID다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARED_USER_NAME IS '공유받은 대상 이름. 공유할 때 저장한 값이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARE_TYPE IS '공유받은 대상 종류: 1 사용자, 0 부서. 별칭 전체(WORLD)는 1이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARED_IS_ALIAS IS '1이면 공유받은 대상 ID가 별칭(V_ECM_ALIASES)이다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.AUTHORITY IS '공유 권한 비트(1 목록 보기, 2 읽기, 4 만들기, 8 수정, 16 삭제, 32 잠금 풀기, 64 권한 변경)를 더한 값이다. 예: 3은 목록 보기와 읽기';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SHARE_DATE IS '공유한 날짜와 시각. 공유가 끝나는 날은 따로 없다';
COMMENT ON COLUMN METAECM.V_ECM_SHARES.SUB_FOLDER_SHARE_YN IS '하위 폴더도 같은 권한으로 공유하는지(Y/N). 문서 공유는 비어 있다';


-- METAECM.V_ECM_USERS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_USERS" ("USER_ID", "EMP_NO", "NAME", "DUTY_ID", "DUTY_NAME", "POSITION_ID", "POSITION_NAME", "USER_JIKGUB", "STATUS", "WORK_GU", "RETIRED_DATE", "DEFAULT_GROUP_ID", "EMAIL", "TELEPHONE") AS
SELECT U.USER_ID, U.EMP_NO, U.NAME, U.DUTY_ID, U.DUTY_NAME, U.POSITION_ID, U.POSITION_NAME, U.USER_JIKGUB, U.STATUS, U.WORK_GU,
       U.RETIRED_DATE,
       (SELECT MIN(G.GROUP_ID) FROM FW_USER_GROUP_LINKS G WHERE G.USER_ID = U.USER_ID AND G.IS_DEFAULT = 1) AS DEFAULT_GROUP_ID,
       U.EMAIL, U.TELEPHONE
FROM FW_USERS U;

COMMENT ON TABLE METAECM.V_ECM_USERS IS '사용자. 사용자 한 명당 한 행. 키는 USER_ID. 퇴직한 사용자도 담고 연락처는 업무 이메일과 전화번호만 둔다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.USER_ID IS 'FW_USERS.USER_ID: 사용자 ID';
COMMENT ON COLUMN METAECM.V_ECM_USERS.EMP_NO IS '사번(FW_USERS.EMP_NO). 인사 연동은 사용자 ID와 같은 값을 넣는다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.NAME IS 'FW_USERS.NAME: 사용자명';
COMMENT ON COLUMN METAECM.V_ECM_USERS.DUTY_ID IS '직위 코드(FW_USERS.DUTY_ID). 인사 연동이 인사 직위 코드를 넣는다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.DUTY_NAME IS '직위 이름(FW_USERS.DUTY_NAME). 인사 연동이 인사 직위 이름을 넣는다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.POSITION_ID IS '직책 코드 칸(FW_USERS.POSITION_ID). 인사 연동이 인사 직종 코드를 넣는다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.POSITION_NAME IS '직책 칸(FW_USERS.POSITION_NAME). 인사 연동이 인사 직종 이름을 넣는다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.USER_JIKGUB IS '직급(FW_USERS.USER_JIKGUB). 관리자가 사용자 관리에서 입력하고 인사 연동은 바꾸지 않는다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.STATUS IS '사용자 상태(FW_USERS.STATUS): CREATED, UPDATED, DELETED. 인사 연동이 퇴직을 처리하면 DELETED다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.WORK_GU IS '재직 구분(FW_USERS.WORK_GU): 재직, 휴직, 퇴직';
COMMENT ON COLUMN METAECM.V_ECM_USERS.RETIRED_DATE IS '퇴사일(FW_USERS.RETIRED_DATE). 인사 연동이 퇴직을 처리한 날짜와 시각이고 다시 재직으로 돌리면 비운다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.DEFAULT_GROUP_ID IS '기본 부서 ID(FW_USER_GROUP_LINKS에서 IS_DEFAULT가 1인 GROUP_ID, 여럿이면 가장 작은 ID). 없으면 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.EMAIL IS '업무 이메일(FW_USERS.EMAIL). 인사 연동이 넣고 퇴직하면 비운다';
COMMENT ON COLUMN METAECM.V_ECM_USERS.TELEPHONE IS '업무 전화번호(FW_USERS.TELEPHONE). 인사 연동이 사무실 전화번호를 넣는다';


-- METAECM.V_ECM_USER_GROUPS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_USER_GROUPS" ("USER_ID", "GROUP_ID", "IS_DEFAULT", "START_DATE", "END_DATE") AS
SELECT L.USER_ID, L.GROUP_ID, L.IS_DEFAULT, L.START_DATE, L.END_DATE
FROM FW_USER_GROUP_LINKS L;

COMMENT ON TABLE METAECM.V_ECM_USER_GROUPS IS '사용자의 부서 소속(기본 부서와 겸직). 소속 하나당 한 행. 키는 USER_ID와 GROUP_ID';
COMMENT ON COLUMN METAECM.V_ECM_USER_GROUPS.USER_ID IS 'FW_USER_GROUP_LINKS.USER_ID: 사용자 ID';
COMMENT ON COLUMN METAECM.V_ECM_USER_GROUPS.GROUP_ID IS '소속 부서 ID(FW_USER_GROUP_LINKS.GROUP_ID)';
COMMENT ON COLUMN METAECM.V_ECM_USER_GROUPS.IS_DEFAULT IS '기본 부서 여부(FW_USER_GROUP_LINKS.IS_DEFAULT): 1 기본 부서, 0 겸직';
COMMENT ON COLUMN METAECM.V_ECM_USER_GROUPS.START_DATE IS '겸직 시작일(FW_USER_GROUP_LINKS.START_DATE, YYYYMMDD 글자). 기본 부서 소속은 비어 있다';
COMMENT ON COLUMN METAECM.V_ECM_USER_GROUPS.END_DATE IS '겸직 끝일(FW_USER_GROUP_LINKS.END_DATE, YYYYMMDD 글자). 기본 부서 소속은 비어 있다';


-- METAECM.V_ECM_USER_PRINCIPALS source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_USER_PRINCIPALS" ("USER_ID", "PRINCIPAL_TYPE", "PRINCIPAL_ID") AS
SELECT U.USER_ID, 'USER' AS PRINCIPAL_TYPE, U.USER_ID AS PRINCIPAL_ID
FROM FW_USERS U
UNION ALL
SELECT U.USER_ID, 'ALIAS' AS PRINCIPAL_TYPE, 'WORLD' AS PRINCIPAL_ID
FROM FW_USERS U
UNION ALL
SELECT L.USER_ID, 'DEPT' AS PRINCIPAL_TYPE, L.GROUP_ID AS PRINCIPAL_ID
FROM FW_USER_GROUP_LINKS L
WHERE EXISTS (SELECT 1 FROM FW_USERS U WHERE U.USER_ID = L.USER_ID)
UNION ALL
SELECT M.USER_ID, 'PROJECT_GROUP' AS PRINCIPAL_TYPE, M.GROUP_ID AS PRINCIPAL_ID
FROM V_ECM_PROJECT_GROUP_USERS M
WHERE EXISTS (SELECT 1 FROM FW_USERS U WHERE U.USER_ID = M.USER_ID)
UNION ALL
SELECT L.USER_ID, 'ROLE' AS PRINCIPAL_TYPE, L.ROLE_ID AS PRINCIPAL_ID
FROM FW_USER_ROLE_LINKS L
         JOIN FW_ROLES R ON R.ROLE_ID = L.ROLE_ID
WHERE EXISTS (SELECT 1 FROM FW_USERS U WHERE U.USER_ID = L.USER_ID);

COMMENT ON TABLE METAECM.V_ECM_USER_PRINCIPALS IS '사용자별 대상. 사용자 한 명과 그 사용자가 해당하는 대상 하나당 한 행. 키는 USER_ID, PRINCIPAL_TYPE, PRINCIPAL_ID. 퇴직한 사용자를 포함해 모든 사용자를 담는다';
COMMENT ON COLUMN METAECM.V_ECM_USER_PRINCIPALS.USER_ID IS '사용자 ID(V_ECM_USERS.USER_ID)';
COMMENT ON COLUMN METAECM.V_ECM_USER_PRINCIPALS.PRINCIPAL_TYPE IS '대상 종류: USER 사용자 자신, ALIAS 별칭 전체(WORLD), DEPT 소속 부서(기본 부서와 겸직 모두, 기간과 상위 부서는 보지 않음), PROJECT_GROUP 멤버로 든 프로젝트 그룹(V_ECM_PROJECT_GROUP_USERS에서 멤버 ID가 사용자 ID인 것), ROLE 가진 역할';
COMMENT ON COLUMN METAECM.V_ECM_USER_PRINCIPALS.PRINCIPAL_ID IS '대상 ID. USER는 사용자 ID, ALIAS는 WORLD, DEPT는 부서 ID, PROJECT_GROUP은 프로젝트 그룹 ID, ROLE은 역할 ID이고 V_ECM_ACL_READERS의 같은 종류 대상 ID와 같은 값이다. 임원 그룹(ALIAS_EXEC)과 회사실적조회 그룹(ALIAS_PERF)은 구성원을 정한 곳이 아직 없어 줄이 없다';


-- METAECM.V_ECM_USER_ROLES source

CREATE OR REPLACE FORCE VIEW "METAECM"."V_ECM_USER_ROLES" ("USER_ID", "ROLE_ID") AS
SELECT L.USER_ID, L.ROLE_ID
FROM FW_USER_ROLE_LINKS L;

COMMENT ON TABLE METAECM.V_ECM_USER_ROLES IS '사용자의 역할. 사용자와 역할 한 쌍당 한 행. 키는 USER_ID와 ROLE_ID';
COMMENT ON COLUMN METAECM.V_ECM_USER_ROLES.USER_ID IS 'FW_USER_ROLE_LINKS.USER_ID: 사용자 ID';
COMMENT ON COLUMN METAECM.V_ECM_USER_ROLES.ROLE_ID IS 'FW_USER_ROLE_LINKS.ROLE_ID: 롤 ID';